---
/**
 * notes.astro — the Notes index: Condensed doctrine + Hubs, with icons.
 * Lists live in src/lib/icons.ts (kept aligned with notes/index.md for agents/Obsidian).
 */
import Base from '../layouts/Base.astro';
import Constellation from '../components/Constellation.astro';
import Icon from '../components/Icon.astro';
import { CONDENSED_ENTRIES, HUB_ENTRIES } from '../lib/icons';
import { slugifyFilePath, slugToUrl } from '../lib/slug';

const href = (slug: string) => slugToUrl(slugifyFilePath(slug));
---

<Base title="Notes" description="The best pages to start reading the wiki." active="notes">
  <main class="notes-page">
    <div class="wrap">
      <Constellation mode="full" height="clamp(340px, 56vh, 580px)" />

      <article class="notes-body">
        <p class="notes-lede">
          Use search (⌘K) or the <a href="/map/">Map</a> to browse by connection.
        </p>

        <h2 class="notes-head">Condensed</h2>
        <p class="notes-sub">Each of these sums up one subject in short rules.</p>
        <ul class="entry-list">
          {CONDENSED_ENTRIES.map((e) => (
            <li>
              <a href={href(e.slug)}>
                <Icon name={e.icon} size="17px" class="entry-list__icon" style={`color:${e.color}`} />
                <span class="entry-list__body">
                  <span class="entry-list__title">{e.title}</span><span class="entry-list__blurb">: {e.blurb}</span>
                </span>
              </a>
            </li>
          ))}
        </ul>

        <h2 class="notes-head">Hubs</h2>
        <p class="notes-sub">Each of these is the starting point for one subject.</p>
        <ul class="entry-list">
          {HUB_ENTRIES.map((e) => (
            <li>
              <a href={href(e.slug)}>
                <Icon name={e.icon} size="17px" class="entry-list__icon" style={`color:${e.color}`} />
                <span class="entry-list__body">
                  <span class="entry-list__title">{e.title}</span><span class="entry-list__blurb">: {e.blurb}</span>
                </span>
              </a>
            </li>
          ))}
        </ul>
      </article>
    </div>
  </main>
</Base>

<style>
  .wrap {
    max-width: var(--kb-content);
    margin: 0 auto;
    padding: 28px 28px 52px;
  }
  .notes-body {
    margin-top: 26px;
  }
  .notes-lede {
    font-family: var(--ming);
    font-size: var(--kb-text-body);
    line-height: var(--kb-lh-body);
    color: var(--mut);
    margin: 0 0 1.4rem;
  }
  .notes-lede a {
    color: var(--accent);
    text-decoration: none;
    border-bottom: 1px solid color-mix(in oklab, var(--accent) 35%, transparent);
  }
  .notes-lede a:hover {
    border-bottom-color: var(--accent);
  }
  .notes-head {
    font-family: var(--ming);
    font-size: 1.15rem;
    font-weight: 600;
    color: var(--ink);
    margin: 1.6rem 0 0.35rem;
  }
  .notes-sub {
    font-size: var(--kb-text-base);
    line-height: var(--kb-lh-body);
    color: var(--mut);
    margin: 0 0 0.75rem;
    max-width: 64ch;
  }
  .entry-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.55rem;
  }
  .entry-list a {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    text-decoration: none;
    color: inherit;
  }
  .entry-list a:hover .entry-list__title {
    color: var(--accent);
  }
  .entry-list a :global(.entry-list__icon) {
    flex-shrink: 0;
    margin-top: 2px;
  }
  .entry-list__body {
    font-size: var(--kb-text-base);
    line-height: var(--kb-lh-body);
    color: var(--mut);
    min-width: 0;
  }
  .entry-list__title {
    color: var(--ink);
    font-weight: 500;
  }
  .entry-list__blurb {
    color: var(--mut);
  }
  @media (max-width: 640px) {
    .wrap {
      padding: 28px 16px 40px;
    }
  }
</style>

/**
 * icons.ts — Tabler icon + domain-color map for entry points (domains, condensed, hubs).
 * Single source so Home, Map, Notes, and domain pages stay in visual lockstep.
 */
import type { Domain } from './types';

export const DOMAIN_ICONS: Record<Domain, string> = {
  learning: 'ti-school',
  agentic: 'ti-robot',
  language: 'ti-language',
  focus: 'ti-target',
  mind: 'ti-brain',
  gen: 'ti-bulb',
};

export type EntryIcon = { icon: string; color: string };

/** Condensed doctrine pages — Notes index. */
export const CONDENSED_ENTRIES: {
  title: string;
  slug: string;
  blurb: string;
  icon: string;
  color: string;
}[] = [
  {
    title: 'Learning, Condensed',
    slug: 'wiki/Syntheses/Learning, Condensed',
    blurb: 'Taking in new material, remembering it, and planning your study.',
    icon: 'ti-school',
    color: 'var(--d-learning)',
  },
  {
    title: 'Chinese Characters, Condensed',
    slug: 'wiki/Language/Chinese/Chinese Characters, Condensed',
    blurb: 'Learning Chinese characters. The parts of a character give clues to its sound and meaning.',
    icon: 'ti-language',
    color: 'var(--d-language)',
  },
  {
    title: 'Agentic Engineering, Condensed',
    slug: 'wiki/Systems/AI & Agentic Systems/Agentic Engineering, Condensed',
    blurb: 'Building software with AI agents. Rules that last are separated from tips that go out of date.',
    icon: 'ti-robot',
    color: 'var(--d-agentic)',
  },
  {
    title: 'Money, Condensed',
    slug: 'wiki/Money/Money, Condensed',
    blurb: 'Doing well with money depends more on habits than on intelligence.',
    icon: 'ti-wallet',
    color: 'var(--d-gen)',
  },
  {
    title: 'Minimalism, Condensed',
    slug: 'wiki/Minimalism/Minimalism, Condensed',
    blurb: 'Every object you own uses up some of your attention.',
    icon: 'ti-box',
    color: 'var(--d-focus)',
  },
  {
    title: 'Design, Condensed',
    slug: 'wiki/Design/Design, Condensed',
    blurb: 'If people struggle to use something, the design is bad.',
    icon: 'ti-palette',
    color: 'var(--d-gen)',
  },
  {
    title: 'Story Craft, Condensed',
    slug: 'wiki/Story Craft/Story Craft, Condensed',
    blurb: 'Writing stories for language learners. The stories use only words the reader already knows.',
    icon: 'ti-book',
    color: 'var(--d-mind)',
  },
];

/** Cluster hubs — Notes index. */
export const HUB_ENTRIES: {
  title: string;
  slug: string;
  blurb: string;
  icon: string;
  color: string;
}[] = [
  {
    title: 'Learning Systems',
    slug: 'wiki/Syntheses/First Principles of Learning',
    blurb: 'How learning works. A study technique is useful only if it makes you process the material in your mind.',
    icon: 'ti-network',
    color: 'var(--d-learning)',
  },
  {
    title: 'Agentic Engineering',
    slug: 'wiki/Systems/AI & Agentic Systems/Agentic Engineering',
    blurb: 'AI agents write much of the code, and the developer is still responsible for it.',
    icon: 'ti-robot',
    color: 'var(--d-agentic)',
  },
  {
    title: 'Language Learning',
    slug: 'wiki/Language/Refold Language Learning System',
    blurb: 'Learning a language by listening and reading a lot.',
    icon: 'ti-language',
    color: 'var(--d-language)',
  },
  {
    title: 'Chinese Characters',
    slug: 'wiki/Language/Chinese/How Chinese Characters Work',
    blurb: 'How Chinese characters are built. Each character is made of smaller parts, and each part has a different function.',
    icon: 'ti-letter-case',
    color: 'var(--d-language)',
  },
  {
    title: 'Attention & Self-Management',
    slug: 'wiki/Self Management/Focus Management - How to Enter & Recover Inside a Work Block',
    blurb: 'Focus and your own attention. Flow is being fully absorbed in a task.',
    icon: 'ti-target',
    color: 'var(--d-focus)',
  },
  {
    title: 'Minimalism',
    slug: 'wiki/Minimalism/Minimalism as Systems Design',
    blurb: 'Owning fewer things. A possession costs attention, space and upkeep.',
    icon: 'ti-box',
    color: 'var(--d-focus)',
  },
  {
    title: 'Red Team / Critical Thinking',
    slug: 'wiki/Red Team/Red Teaming',
    blurb: 'Attacking your own plan before you carry it out.',
    icon: 'ti-shield',
    color: 'var(--d-mind)',
  },
  {
    title: 'Front-End Web Design',
    slug: 'wiki/Design/Front-End Web Design',
    blurb: 'Design rules for web pages. The screen has to show people what they can click.',
    icon: 'ti-layout',
    color: 'var(--d-gen)',
  },
  {
    title: 'Story Craft',
    slug: 'wiki/Story Craft/Story Craft',
    blurb: 'Building characters who stay believable across a long story.',
    icon: 'ti-book',
    color: 'var(--d-mind)',
  },
];

