---
/**
 * Note.astro — the per-note page layout.
 * Replicates the DS NotePage (ui_kits/knowledge-base/screens.jsx): a two-column
 * grid `minmax(0,1fr) 240px` inside the 1080px container, with
 *   left  = <article data-pagefind-body> : mono breadcrumb, Ming <h1>, meta row
 *           (domain-colored pill type tag + "updated …"), then the prose <slot/>
 *           in the Ming serif at max ~64ch.
 *   right = sticky aside rail (top:80px) = constellation neighborhood + Toc + Backlinks.
 *
 * Wraps Base (which owns <html data-accent="violet">, the DS css imports, the
 * no-flash theme script, Chrome + Footer). All tokens are DS custom properties.
 */
import Base from './Base.astro';
import Toc from '../components/Toc.astro';
import Backlinks from '../components/Backlinks.astro';
import Constellation from '../components/Constellation.astro';
import type { Domain, GraphData, Backlink } from '../lib/types';

interface Heading {
  depth: number;
  text: string;
  slug: string;
}

interface Props {
  title: string;
  type?: string;
  updated?: string;
  domain: Domain | string;
  slug: string;
  headings: Heading[];
  backlinks: Backlink[];
  /** Unused now — the local graph slices /graph.json client-side. Kept so callers don't break. */
  local?: GraphData;
  active?: string;
}

const { title, type, updated, domain, slug, headings, backlinks, active } = Astro.props;

// Breadcrumb from the folder slug: "wiki/Concepts/Higher-Order-Generativity" →
// "wiki / Concepts / Higher-Order Generativity" (DS .crumb / NotePage breadcrumb).
const crumbParts = slug
  .replace(/^\/+/, '')
  .replace(/\/+$/, '')
  .split('/')
  .filter(Boolean)
  .map((p) => p.replace(/--and--/g, ' & ').replace(/-+/g, ' '));
const breadcrumb = crumbParts.length ? crumbParts.join(' / ') : title;
// Each crumb is a link (owner, 2026-09-05: "i also want (and expected) these to be clickable links").
// The first part ("wiki", "personal", "journal") goes to the notes index, every folder part goes to
// the page's domain map, and the last part is the page itself, so it stays plain text.
const crumbs = crumbParts.map((label, i) => ({
  label,
  href: i === crumbParts.length - 1 ? null : i === 0 ? '/notes/' : `/domains/${domain}/`,
}));

const domainVar = `var(--d-${domain})`;
const hasAside = true;
---

<Base title={title} description={updated ? `Updated ${updated}` : undefined} active={active}>
  <main class="kb-note-main">
    <div class="kb-note-grid">
      <article
        data-pagefind-body
        data-pagefind-meta={`domain:${domain}`}
        data-pagefind-meta={`title:${title}`}
      >
        <div class="kb-crumb" aria-label={breadcrumb}>
          {
            crumbs.length
              ? crumbs.map((c, i) => (
                  <Fragment>
                    {i > 0 && <span class="kb-crumb-sep"> / </span>}
                    {c.href ? <a href={c.href}>{c.label}</a> : <span>{c.label}</span>}
                  </Fragment>
                ))
              : title
          }
        </div>
        <h1 class="kb-note-title">{title}</h1>
        <div class="kb-note-meta">
          {
            type && (
              <span class="kb-type-tag" style={`border-color:${domainVar};color:${domainVar}`}>
                {type}
              </span>
            )
          }
          {updated && <span>updated {updated}</span>}
        </div>
        <div class="kb-prose">
          <slot />
        </div>
      </article>

      {
        hasAside && (
          <aside class="kb-note-aside">
            <div class="kb-localgraph-wrap" aria-hidden="true">
              <Constellation mode="local" seeds={[slug]} hops={2} height="118px" />
            </div>
            <Toc headings={headings} />
            <Backlinks items={backlinks} />
          </aside>
        )
      }
    </div>
  </main>
</Base>

<style>
  .kb-note-main {
    flex: 1;
  }
  .kb-note-grid {
    max-width: 1080px;
    margin: 0 auto;
    padding: 34px 32px 0;

---
/**
 * [...slug].astro — every note page.
 *
 * One route per published note: getStaticPaths() walks getCollection('notes') and emits a path per
 * entry, keyed by the Quartz slug (`simplifySlug(entry.id)`), SKIPPING the home entry (simplifySlug
 * === '/') which index.astro owns. Each path carries its entry as a prop.
 *
 * Rendering: `render(entry)` gives the compiled <Content/> + Astro `headings`. The global link graph
 * and backlink index are built ONCE (module-level memo, shared across every generated page) over all
 * notes, then sliced per note — localGraph(graph, id, 2) for the rail, backlinks[id] for the panel.
 * Title via deriveTitle, domain via resolveDomain. Everything is handed to <Note/>, which wraps Base.
 */
import { getCollection, render } from 'astro:content';
import type { GetStaticPaths } from 'astro';
import Note from '../layouts/Note.astro';
import { deriveTitle } from '../lib/note';
import { resolveDomain } from '../lib/domain';
import { simplifySlug } from '../lib/slug';
import { buildGraph, localGraph, type NoteInput as GraphNoteInput } from '../lib/graph';
import { buildBacklinks, type NoteInput as BacklinkNoteInput } from '../lib/backlinks';
import type { GraphData, BacklinkIndex } from '../lib/types';

export const getStaticPaths = (async () => {
  const notes = await getCollection('notes');
  return notes
    // index.md (simplifySlug → '/') is rendered by index.astro; notes/index by notes.astro.
    .filter((entry) => simplifySlug(entry.id) !== '/' && entry.id !== 'notes/index')
    .map((entry) => ({
      params: { slug: simplifySlug(entry.id) },
      props: { entry },
    }));
}) satisfies GetStaticPaths;

/* ── module-level memo: build the global graph + backlinks exactly once ─────── */
let graphMemo: GraphData | null = null;
let backlinksMemo: BacklinkIndex | null = null;

async function getGlobalIndices(): Promise<{ graph: GraphData; backlinks: BacklinkIndex }> {
  if (graphMemo && backlinksMemo) return { graph: graphMemo, backlinks: backlinksMemo };
  const notes = await getCollection('notes');
  const graphInput: GraphNoteInput[] = notes.map((n) => ({
    slug: n.id,
    title: deriveTitle(n.data, n.id, n.body),
    type: typeof n.data.type === 'string' ? n.data.type : '',
    body: n.body ?? '',
  }));
  const backlinkInput: BacklinkNoteInput[] = notes.map((n) => ({
    slug: n.id,
    title: deriveTitle(n.data, n.id, n.body),
    body: n.body ?? '',
  }));
  graphMemo = buildGraph(graphInput);
  backlinksMemo = buildBacklinks(backlinkInput);
  return { graph: graphMemo, backlinks: backlinksMemo };
}

const { entry } = Astro.props as { entry: Awaited<ReturnType<typeof getCollection>>[number] };

const { Content, headings } = await render(entry);

const title = deriveTitle(entry.data, entry.id, entry.body);
const domain = resolveDomain(entry.id);
const type = typeof entry.data.type === 'string' ? entry.data.type : undefined;
const updated =
  entry.data.updated instanceof Date
    ? entry.data.updated.toISOString().slice(0, 10)
    : typeof entry.data.updated === 'string'
      ? entry.data.updated
      : undefined;

const { graph, backlinks } = await getGlobalIndices();
const local = localGraph(graph, entry.id, 2);
const noteBacklinks = backlinks[entry.id] ?? [];

// Astro headings → the {depth,text,slug} shape Toc/Note expect.
const tocHeadings = headings.map((h) => ({ depth: h.depth, text: h.text, slug: h.slug }));
---

<Note
  title={title}
  type={type}
  updated={updated}
  domain={domain}
  slug={entry.id}
  headings={tocHeadings}
  backlinks={noteBacklinks}
  local={local}
>
  <Content />
</Note>

---
/**
 * map.astro — the Map: the full VAULT GRAPH on top (every note + link), then the six domains listed
 * below as a plain index. The per-domain page lists are computed from the live collection
 * (doctrine-first, knowledge pages only), so they stay current as the vault grows.
 */
import { getCollection } from 'astro:content';
import Base from '../layouts/Base.astro';
import Constellation from '../components/Constellation.astro';
import { buildGraph, type NoteInput } from '../lib/graph';
import { deriveTitle } from '../lib/note';
import { slugToUrl } from '../lib/slug';
import { DOMAINS, DOMAIN_LABELS } from '../lib/types';
import { DOMAIN_ICONS } from '../lib/icons';
import Icon from '../components/Icon.astro';

const PER_SECTION = 8;

// One concrete line per domain: a real idea from inside it, useful to the reader — never a
// restatement of the category (the heading and the list already say what it is). Front-facing:
// 02 - System/Writing Standards.md → Specific Beats Generic, Details Not Conclusions (no A-is-A).
const DOMAIN_BLURB: Record<string, string> = {
  learning: 'Retrieval and spacing help you remember what you read.',
  agentic: 'When agents write the code, your job is to direct them well.',
  language: 'Chinese characters are built from a few hundred reusable parts.',
  focus: 'Attention is limited, and a feed decides where yours goes.',
  mind: 'Decisions improve when you red-team your own reasoning first.',
  gen: 'Wealth is owning part of something that grows without more of your time.',
};

// Doctrine-first ordering: hubs and condensed pages lead, then syntheses, then supporting types,
// with link degree as the tiebreaker. New pages slot in by type, so it stays sensible as it grows.
const TYPE_RANK: Record<string, number> = {
  hub: 100,
  synthesis: 80,
  system: 70,
  model: 60,
  dimension: 60,
  pillar: 45,
  primer: 40,
  workflow: 35,
  technique: 25,
  concept: 20,
  book: 15,
};

const notes = await getCollection('notes');
const input: NoteInput[] = notes.map((n) => ({
  slug: n.id,
  title: deriveTitle(n.data, n.id, n.body),
  type: typeof n.data.type === 'string' ? n.data.type : '',
  body: n.body ?? '',
}));
const full = buildGraph(input);

const degree = new Map<string, number>();
for (const e of full.edges) {
  degree.set(e.source, (degree.get(e.source) ?? 0) + 1);
  degree.set(e.target, (degree.get(e.target) ?? 0) + 1);
}
const score = (n: (typeof full.nodes)[number]) => {
  const tier = Math.max(TYPE_RANK[n.type] ?? 12, /,\s*Condensed$/i.test(n.title) ? 90 : 0);
  return tier * 1000 + (degree.get(n.slug) ?? 0);
};

const byDomain = new Map<string, (typeof full.nodes)[number][]>();
for (const n of full.nodes) {
  if (!n.slug.startsWith('wiki/')) continue; // knowledge pages only — exclude journal, index, about
  (byDomain.get(n.domain) ?? byDomain.set(n.domain, []).get(n.domain)!).push(n);
}

const sections = DOMAINS.map((d) => {
  const all = (byDomain.get(d) ?? []).sort((a, b) => score(b) - score(a) || a.title.localeCompare(b.title));
  return {
    domain: d,
    label: DOMAIN_LABELS[d],
    icon: DOMAIN_ICONS[d],
    items: all.slice(0, PER_SECTION),
  };
});

---
/**
 * Backlinks.astro — "Backlinks · N" sticky-aside panel.
 * Mirrors the NotePage aside backlinks block in the DS screens.jsx: mono uppercase
 * heading with the count, each entry a title link (var(--ink)) with a hairline
 * bottom rule and a faint context line below it.
 */
import type { Backlink } from '../lib/types';

interface Props {
  items: Backlink[];
}
const { items } = Astro.props;
const slugToHref = (slug: string) => '/' + slug.replace(/^\/+/, '').replace(/\/+$/, '') + '/';
---

{
  items.length > 0 && (
    <section class="kb-backlinks" aria-label="Backlinks">
      <h3 class="kb-side-h">Backlinks · {items.length}</h3>
      <div class="kb-backlinks-list">
        {items.map((b) => (
          <a href={slugToHref(b.slug)} class="kb-backlink">
            {b.title}
            {b.context && <span class="kb-backlink-ctx">{b.context}</span>}
          </a>
        ))}
      </div>
    </section>
  )
}

<style>
  .kb-side-h {
    font-family: var(--mono);
    font-size: 9.5px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--mut);
    margin: 0 0 10px;
    font-weight: 600;
  }
  .kb-backlinks-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }
  .kb-backlink {
    font-size: 13px;
    color: var(--ink);
    text-decoration: none;
    border-bottom: 1px solid var(--rule);
    padding-bottom: 7px;
  }
  .kb-backlink:hover {
    color: var(--accent);
  }
  .kb-backlink-ctx {
    display: block;
    font-size: 11px;
    color: var(--faint);
    margin-top: 2px;
  }
</style>

});
---

<Base title="Map" description="The vault graph, and the knowledge base by domain." active="map">
  <main class="map-page">
    <div class="wrap">
      <header class="map-head">
        <h1 class="map-head__title">The vault</h1>
      </header>

      <Constellation mode="full" domainLabels height="clamp(460px, 66vh, 780px)" />
    </div>

    <article class="prose">
      <h2 class="prose__head">The six domains</h2>
      {sections.map((s) => (
        <section class="domain">
          <h3>
            <a href={`/domains/${s.domain}/`}>
              <Icon name={s.icon} size="1.05em" class="domain__icon" style={`color:var(--d-${s.domain})`} />
              {s.label}
            </a>
          </h3>
          <p class="domain__blurb">{DOMAIN_BLURB[s.domain]}</p>
          <ul>
            {s.items.map((it) => (
              <li>
                <a href={slugToUrl(it.slug)}>{it.title}</a>
              </li>
            ))}
          </ul>
        </section>
      ))}
    </article>
  </main>
</Base>

<style>
  .wrap {
    max-width: var(--kb-content);
    margin: 0 auto;
    padding: 28px 28px 0;
  }
  .map-head {
    max-width: 60ch;
    margin: 8px 0 16px;
  }
  .map-head__title {
    font-family: var(--ming);
    font-weight: 500;

---
import Base from '../layouts/Base.astro';
import Constellation from '../components/Constellation.astro';
---

<Base title="Graph" description="Full vault link graph." active="notes">
  <main class="graph-page">
    <div class="wrap">
      <header class="head">
        <h1>Vault graph</h1>
        <p>Hover to highlight neighborhoods · click a node to open the note · scroll to zoom · drag to pan</p>
      </header>
      <Constellation mode="full" height="min(78vh, 720px)" />
    </div>
  </main>
</Base>

<style>
  .wrap {
    max-width: var(--kb-content);
    margin: 0 auto;
    padding: 0 32px 36px;
  }
  .head {
    padding: 34px 0 16px;
  }
  .head h1 {
    font-family: var(--ming);
    font-size: 32px;
    margin: 0;
  }
  .head p {
    margin: 8px 0 0;
    font-size: 13px;
    color: var(--faint);
  }
</style>

---
/**
 * domains/[domain].astro — per-domain Map of Content. Journal-style spread: the page list on the
 * left (2/3) and the domain's sub-graph as a vertical constellation on the right (1/3). Reached by
 * clicking a legend chip on the home graph.
 */
import { getCollection } from 'astro:content';
import Base from '../../layouts/Base.astro';
import Constellation from '../../components/Constellation.astro';
import { deriveTitle, deriveSummary } from '../../lib/note';
import { resolveDomain } from '../../lib/domain';
