--- /dev/null
+++ b//tmp/verify-logos52-main-drive.cjs
@@ -1,0 +1,220 @@
+const puppeteer = require('/tmp/puppeteer-run/node_modules/puppeteer-core');
+const fs = require('fs');
+const path = require('path');
+
+const BASE = 'http://127.0.0.1:4321';
+const OUT = '/opt/cursor/artifacts/verify-logos52';
+fs.mkdirSync(OUT, { recursive: true });
+const checks = [];
+function check(name, ok, detail) {
+  checks.push({ name, ok, detail });
+  console.log((ok ? 'PASS' : 'FAIL') + ' ' + name + ' ' + JSON.stringify(detail).slice(0, 400));
+}
+async function snap(page, name) {
+  await page.screenshot({ path: path.join(OUT, name + '.png') });
+}
+
+(async () => {
+  const browser = await puppeteer.launch({
+    executablePath: '/usr/local/bin/google-chrome',
+    headless: false,
+    defaultViewport: { width: 1400, height: 900 },
+    args: ['--no-sandbox', '--disable-dev-shm-usage', '--window-size=1400,900', '--window-position=40,40'],
+    env: { ...process.env, DISPLAY: process.env.DISPLAY || ':1' },
+  });
+  const page = await browser.newPage();
+  page.setDefaultTimeout(25000);
+
+  await page.goto(BASE + '/', { waitUntil: 'networkidle0' });
+  await page.waitForSelector('h1.hero__title');
+  await page.waitForSelector('section.start-here');
+  const home = await page.evaluate(() => ({
+    h1: document.querySelector('h1.hero__title').textContent.trim(),
+    mode: document.querySelector('[data-constellation-root]')?.getAttribute('data-mode'),
+    doors: [...document.querySelectorAll('a.door')].map((a) => ({
+      intent: a.querySelector('.door__intent')?.textContent.trim(),
+      href: a.getAttribute('href'),
+    })),
+    topmind: document.querySelectorAll('.topmind__item').length,
+    hubs: document.querySelectorAll('.hub-card').length,
+    navOn: [...document.querySelectorAll('a.kb-nav__link.on')].map((a) => a.textContent.trim()),
+  }));
+  check('home', home.h1 === 'LLM Knowledge Base' && home.mode === 'spine' && home.doors.length === 5 && home.topmind === 4 && home.hubs === 3 && home.navOn.length === 0, home);
+  await snap(page, 'main-home');
+
+  await page.evaluate(() => {
+    [...document.querySelectorAll('a.door')].find((a) => a.querySelector('.door__intent').textContent.trim() === 'Explore').click();
+  });
+  await page.waitForFunction(() => /\/map\/?$/.test(location.pathname) && document.querySelector('h1.map-head__title'));
+  const map = await page.evaluate(() => ({
+    url: location.pathname,
+    h1: document.querySelector('h1.map-head__title').textContent.trim(),
+    mode: document.querySelector('[data-constellation-root]')?.getAttribute('data-mode'),
+    domainLabels: document.querySelector('[data-constellation-root]')?.hasAttribute('data-domain-labels'),
+    canvas: !!document.querySelector('canvas'),
+    unavailable: document.body.textContent.includes('Graph data unavailable.'),
+    six: document.querySelector('h2.prose__head')?.textContent.trim(),
+    blurbs: document.querySelectorAll('.domain__blurb').length,
+    domains: [...document.querySelectorAll('section.domain h3 a')].map((a) => ({
+      text: a.textContent.trim(),
+      href: a.getAttribute('href'),
+    })),
+    navOn: [...document.querySelectorAll('a.kb-nav__link.on')].map((a) => a.textContent.trim()),
+  }));
+  check('map', map.h1 === 'The vault' && map.mode === 'full' && map.canvas && map.domainLabels && map.navOn[0] === 'Map' && !map.unavailable && map.six === 'The six domains', map);
+  await snap(page, 'main-map');
+
+  await page.evaluate(() => {
+    [...document.querySelectorAll('section.domain h3 a')].find((a) => a.textContent.includes('Learning')).click();
+  });
+  await page.waitForFunction(() => /\/domains\/learning\/?$/.test(location.pathname));
+  await page.waitForSelector('ul.moc');
+  const domain = await page.evaluate(() => ({
+    url: location.pathname,
+    h1: document.querySelector('h1').textContent.replace(/\s+/g, ' ').trim(),
+    moc: document.querySelectorAll('ul.moc a').length,
+    navOn: [...document.querySelectorAll('a.kb-nav__link.on')].map((a) => a.textContent.trim()),
+    back: document.querySelector('a.head__kind')?.getAttribute('href'),
+  }));
+  check('domain', /Learning/.test(domain.h1) && domain.moc > 0 && domain.navOn[0] === 'Notes' && domain.back === '/map/', domain);
+  await snap(page, 'main-domain-learning');
+
+  await page.goto(BASE + '/', { waitUntil: 'networkidle0' });
+  await page.evaluate(() => {
+    [...document.querySelectorAll('a.door')].find((a) => a.querySelector('.door__intent').textContent.trim() === 'Understand').click();
+  });
+  await page.waitForSelector('h1.kb-note-title');
+  const note = await page.evaluate(() => ({
+    url: location.pathname,
+    h1: document.querySelector('h1.kb-note-title').textContent.trim(),
+    pill: document.querySelector('.kb-type-tag')?.textContent.trim() || null,
+    dek: document.querySelector('.kb-note-dek')?.textContent.trim() || null,
+    crumbs: [...document.querySelectorAll('.kb-crumb a')].map((a) => ({ t: a.textContent.trim(), href: a.getAttribute('href') })),
+    related: document.querySelector('details.kb-related-more summary')?.textContent.trim() || null,
+    backlinks: document.querySelectorAll('section.kb-backlinks a.kb-backlink').length,
+    backMore: document.querySelector('details.kb-backlinks-more summary')?.textContent.trim() || null,
+    local: document.querySelector('[data-constellation-root]')?.getAttribute('data-mode'),
+    toc: !!document.querySelector('nav.kb-toc[aria-label="Contents"]'),
+  }));
+  check(
+    'understand',
+    note.h1 === 'The AI Industrial Revolution' &&
+      note.pill === 'Concept' &&
+      !note.dek &&
+      note.crumbs[0]?.href === '/folder/wiki/' &&
+      note.local === 'local' &&
+      !!note.related,
+    note,
+  );
+  await snap(page, 'main-understand');
+
+  const prose = await page.evaluate(() => {
+    const a = [...document.querySelectorAll('.kb-prose a')].find(
+      (el) => !el.closest('details') && el.getAttribute('href') && !el.getAttribute('href').startsWith('#'),
+    );
+    if (!a) return null;
+    const info = { text: a.textContent.trim().slice(0, 100), href: a.getAttribute('href') };
+    a.click();
+    return info;
+  });
+  await page.waitForSelector('h1.kb-note-title');
+  const followed = await page.evaluate(() => ({
+    url: location.pathname,
+    h1: document.querySelector('h1.kb-note-title').textContent.trim(),
+  }));
+  check('prose', !!prose && followed.h1.length > 0 && followed.url !== note.url, { prose, followed });
+  await snap(page, 'main-prose');
+
+  await page.evaluate(() => {
+    [...document.querySelectorAll('a.kb-nav__link')].find((a) => a.textContent.trim() === 'Notes').click();
+  });
+  await page.waitForSelector('main.notes-page');
+  const notes = await page.evaluate(() => ({
+    url: location.pathname,
+    navOn: [...document.querySelectorAll('a.kb-nav__link.on')].map((a) => a.textContent.trim()),
+    heads: [...document.querySelectorAll('h2.notes-head')].map((h) => h.textContent.trim()),
+    mode: document.querySelector('[data-constellation-root]')?.getAttribute('data-mode'),
+    rows: [...document.querySelectorAll('.entry-list a')].map((a) => ({
+      title: a.querySelector('.entry-list__title').textContent.trim(),
+      href: a.getAttribute('href'),
+    })),
+  }));
+  const by = Object.fromEntries(notes.rows.map((r) => [r.title, r.href]));
+  const omitted = ['Using Grok Bot', 'pstack', 'Cursor Cloud Agents', 'Picking a computer'].filter((t) => !by[t]);
+  check(
+    'notes',
+    notes.url === '/notes' &&
+      notes.navOn[0] === 'Notes' &&
+      notes.heads.join(',') === 'Condensed,Hubs' &&
+      notes.mode === 'full' &&
+      by['Learning Systems']?.includes('Are-You-Learning') &&
+      by['Attention & Self-Management']?.includes('Flow-State') &&
+      !!by['Worldviews & the Political Order'] &&
+      omitted.length === 4,
+    { url: notes.url, learning: by['Learning Systems'], attention: by['Attention & Self-Management'], worldviews: by['Worldviews & the Political Order'], omitted, titles: notes.rows.map((r) => r.title) },
+  );
+  await snap(page, 'main-notes');
+
+  await page.evaluate(() => {
+    [...document.querySelectorAll('.entry-list__title')].find((el) => el.textContent.trim() === 'Learning, Condensed').closest('a').click();
+  });
+  await page.waitForSelector('h1.kb-note-title');
+  const lc = await page.evaluate(() => ({
+    h1: document.querySelector('h1.kb-note-title').textContent.trim(),
+    pill: document.querySelector('.kb-type-tag')?.textContent.trim() || null,
+    dek: !!document.querySelector('.kb-note-dek'),
+    crumb: document.querySelector('.kb-crumb a')?.getAttribute('href'),
+  }));
+  check('learning-condensed', lc.h1 === 'Learning, Condensed' && lc.pill === 'Condensed' && lc.dek === true && lc.crumb === '/folder/wiki/', lc);
+  await snap(page, 'main-learning-condensed');
+
+  const indexStatus = await page.goto(BASE + '/notes/index/', { waitUntil: 'domcontentloaded' });
+  check('notes-index-404', indexStatus.status() === 404, { status: indexStatus.status(), url: page.url() });
+
+  await page.goto(BASE + '/', { waitUntil: 'networkidle0' });
+  await page.click('input[aria-label="Search notes"]');
+  await page.type('input[data-search-input]', 'Vibe Coding', { delay: 25 });
+  await page.waitForSelector('[data-search-results] a.kb-ac-row');
+  const search = await page.evaluate(() => {
+    const rows = [...document.querySelectorAll('a.kb-ac-row')].map((a) => ({
+      title: a.querySelector('.kb-ac-title')?.textContent.trim(),
+      domain: a.querySelector('.kb-ac-domain')?.textContent.trim() || null,
+      href: a.getAttribute('href'),
+      excerptText: a.querySelector('.kb-ac-ex')?.textContent.trim().slice(0, 140) || null,
+      excerptHtml: a.querySelector('.kb-ac-ex')?.innerHTML.slice(0, 180) || null,
+    }));
+    return { hidden: document.querySelector('[data-search-results]').hasAttribute('hidden'), n: rows.length, rows };
+  });
+  const first = search.rows[0];
+  check(
+    'search-domain',
+    first?.title === 'Vibe Coding' && first?.domain === 'Agentic' && search.n <= 8 && !search.hidden,
+    search,
+  );
+  check(
+    'search-mark-html',
+    !!first?.excerptHtml && first.excerptHtml.includes('<mark>') && !(first.excerptText || '').includes('<mark>'),
+    { html: first?.excerptHtml, text: first?.excerptText },
+  );
+  await snap(page, 'main-search');
+  await page.click('a.kb-ac-row');
+  await page.waitForSelector('h1.kb-note-title');
+  const landed = await page.evaluate(() => ({
+    h1: document.querySelector('h1.kb-note-title').textContent.trim(),
+    url: location.pathname,
+  }));
+  check(
+    'search-landed',
+    landed.h1 === 'Vibe Coding' && landed.url.includes('AI--and--Agentic-Systems'),
+    landed,
+  );
+  await snap(page, 'main-search-landed');
+
+  await browser.close();
+  const failed = checks.filter((c) => !c.ok);
+  fs.writeFileSync(path.join(OUT, 'main-drive.json'), JSON.stringify({ checks, failed: failed.length }, null, 2));
+  if (failed.length) process.exit(1);
+})().catch((err) => {
+  console.error(err);
+  process.exit(1);
+});

